CREATE COLUMN TABLE "TEST_AP"."APZ_OEMC" ("Code" INTEGER CS_INT NOT NULL , "ServerAddress" VARCHAR(254), "SSLPort" INTEGER CS_INT, "TSLPort" INTEGER CS_INT, "EnableSSL" CHAR(1) CS_FIXEDSTRING, "FullName" NVARCHAR(254), "MailAddress" NVARCHAR(254), "Password" NVARCHAR(500), "UserSign" INTEGER CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "SmtpMethod" CHAR(1) CS_FIXEDSTRING, "UserName" NVARCHAR(254), "ClientId" NVARCHAR(500), "ClientSecret" NVARCHAR(500), "Timeout" INTEGER CS_INT, "UseAuthen" CHAR(1) CS_FIXEDSTRING, PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE 